-- ch12_perfect_forms.sql
-- Latina Exercitia: add the perfect active system (perfect, pluperfect, future perfect) and principal parts
-- to all 32 existing verb drills (Wheelock Capvt XII). The 3rd plural perfect accepts the alternative -ere
-- ending (laudaverunt|laudavere). Needs the matching index.html to show the new tenses (deploy that first).
-- UPDATE file: changes 32 rows, inserts nothing, safe to re-run.
-- Reversible: update drills set content = (content - 'principal_parts') || jsonb_build_object('forms',
--   (content->'forms') - 'perfect' - 'pluperfect' - 'futperfect') where type = 'conjugation';
